-- Fixture for introspection: what the shared app fixture lacks. Partitioned
-- and foreign tables, identity and generated columns, enum arrays, ON DELETE
-- actions, restrictive policies, triggers, functions, column-level grants, a
-- relation and a schema ro_clean cannot read, and names that need quoting.

CREATE SCHEMA lab;
COMMENT ON SCHEMA lab IS 'Introspection lab';

CREATE TYPE lab.mood AS ENUM ('happy', 'it''s complicated', 'sad');

CREATE TABLE lab.parent (
    id     int PRIMARY KEY,
    name   text NOT NULL UNIQUE,
    active tstzrange,
    CONSTRAINT parent_active_excl EXCLUDE USING gist (active WITH &&)
);

CREATE TABLE lab.child (
    id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_id int NOT NULL REFERENCES lab.parent (id) ON DELETE CASCADE,
    price     numeric(10, 2) NOT NULL,
    qty       int NOT NULL DEFAULT 1,
    total     numeric GENERATED ALWAYS AS (price * qty) STORED,
    mood      lab.mood,
    moods     lab.mood[] NOT NULL DEFAULT '{}',
    CONSTRAINT child_qty_positive CHECK (qty > 0),
    CONSTRAINT child_parent_mood_key UNIQUE (parent_id, mood)
);
COMMENT ON TABLE lab.child IS 'Line items.
Second line of the comment.';
COMMENT ON COLUMN lab.child.mood IS 'How it went';

ALTER TABLE lab.child ENABLE ROW LEVEL SECURITY;
CREATE POLICY child_read ON lab.child FOR SELECT TO ro_leaky, ro_clean USING (qty > 0);
CREATE POLICY child_guard ON lab.child AS RESTRICTIVE USING (price >= 0) WITH CHECK (price < 1000);
CREATE POLICY child_insert ON lab.child FOR INSERT WITH CHECK (qty < 100);

CREATE FUNCTION lab.touch() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION lab.touch() FROM PUBLIC;
CREATE TRIGGER child_touch BEFORE UPDATE ON lab.child FOR EACH ROW EXECUTE FUNCTION lab.touch();
CREATE TRIGGER child_audit AFTER INSERT ON lab.child FOR EACH ROW EXECUTE FUNCTION lab.touch();

CREATE FUNCTION lab.child_total(p_parent int) RETURNS numeric
LANGUAGE sql STABLE AS $$ SELECT sum(total) FROM lab.child WHERE parent_id = p_parent $$;
CREATE FUNCTION lab.child_total(p_parent int, p_mood lab.mood) RETURNS numeric
LANGUAGE sql STABLE AS $$ SELECT sum(total) FROM lab.child WHERE parent_id = p_parent AND mood = p_mood $$;

CREATE TABLE lab.measurements (
    id       int NOT NULL,
    taken_on date NOT NULL,
    value    double precision
) PARTITION BY RANGE (taken_on);
CREATE TABLE lab.measurements_2024 PARTITION OF lab.measurements FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE lab.measurements_2025 PARTITION OF lab.measurements FOR VALUES FROM ('2025-01-01') TO ('2026-01-01');
INSERT INTO lab.measurements (id, taken_on, value)
SELECT g, date '2024-01-01' + g, g FROM generate_series(1, 600) AS g;

-- A wrapper with no handler: enough for catalog entries, never queried.
CREATE FOREIGN DATA WRAPPER lab_fdw;
CREATE SERVER lab_server FOREIGN DATA WRAPPER lab_fdw;
CREATE FOREIGN TABLE lab.remote_items (id int, label text) SERVER lab_server;

-- ro_clean may read only id and label.
CREATE TABLE lab.secrets (
    id    int PRIMARY KEY,
    label text,
    token text
);

-- ro_clean may not read it at all.
CREATE TABLE lab.hidden (id int);

CREATE TABLE lab."Mixed Case" ("Weird Col" int);

-- A view whose definition is longer than Render shows.
DO $$
BEGIN
    EXECUTE 'CREATE VIEW lab.wide AS SELECT '
        || (SELECT string_agg(format('%s AS wide_column_%s', g, g), ', ') FROM generate_series(1, 150) AS g);
END $$;

-- ro_clean has no USAGE on this schema.
CREATE SCHEMA locked;
CREATE TABLE locked.vault (id int);
GRANT SELECT ON locked.vault TO ro_clean;

GRANT USAGE ON SCHEMA lab TO ro_clean;
GRANT SELECT ON lab.parent, lab.child, lab.measurements, lab.measurements_2024,
    lab.remote_items, lab.wide, lab."Mixed Case" TO ro_clean;
GRANT SELECT (id, label) ON lab.secrets TO ro_clean;

ANALYZE;
